[CmdletBinding()]
param(
    [Parameter(Mandatory=$true)][string]$ProjectPath,
    [Parameter(Mandatory=$true)][string]$PilotPlanPath,
    [Parameter(Mandatory=$true)][string]$ProvenancePath,
    [string]$UnityPath='H:\UnityEditor\2022.3.30f1c1\Editor\Unity.exe',
    [switch]$BindingSmokeOnly
)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
if([string]::IsNullOrWhiteSpace($ProjectPath)-or-not[IO.Path]::IsPathRooted($ProjectPath)){throw 'PR1B pre-pilot requires an explicit absolute ProjectPath.'};$ProjectPath=[IO.Path]::GetFullPath($ProjectPath)
if($BindingSmokeOnly){Write-Output("BINDING-SMOKE-PASSED|Run-Gate13RPR1BPrePilotV1|$ProjectPath");exit 0}
$PilotPlanPath=[IO.Path]::GetFullPath($PilotPlanPath);$ProvenancePath=[IO.Path]::GetFullPath($ProvenancePath);$UnityPath=[IO.Path]::GetFullPath($UnityPath)
Import-Module (Join-Path $ProjectPath 'Research\Gate13RPR1BOrderEffectPreparationV1.psm1') -Force
$plan=Read-Gate13RPR1BJson $PilotPlanPath;$provenance=Read-Gate13RPR1BJson $ProvenancePath;Assert-Gate13RPR1BPlanIdentity $plan
$root=[IO.Path]::GetFullPath((Join-Path $ProjectPath ([string]$plan.paths.verificationRootRelativePath).Replace('/','\')));$base=[IO.Path]::GetFullPath((Join-Path $ProjectPath 'Research\Verification\Gate12R_ProcessReuse_5pct'))
if(-not$root.StartsWith($base.TrimEnd('\')+'\',[StringComparison]::OrdinalIgnoreCase)){throw 'PR1B verification root is outside versioned Gate12R containment.'};if(Test-Path $root){throw "Create-new verification root exists: $root"}
$pilotRoot=Join-Path $ProjectPath ([string]$plan.paths.pilotRootRelativePath).Replace('/','\');$formalRoot=Join-Path $ProjectPath ([string]$plan.paths.reservedFormalRootRelativePath).Replace('/','\')
if(Test-Path $pilotRoot){throw 'PR1B pilot root must be absent during pre-pilot.'};if(Test-Path $formalRoot){throw 'Reserved formal root must be absent.'};if(@(Get-Process -Name Unity -ErrorAction SilentlyContinue).Count-or(Test-Path (Join-Path $ProjectPath 'Temp\UnityLockfile'))){throw 'Unity must be closed and unlocked before PR1B pre-pilot.'}
foreach($binding in @($provenance.boundFiles)){$path=Join-Path $ProjectPath ([string]$binding.relativePath).Replace('/','\');if(-not(Test-Path $path)-or(Get-Gate13RPR1BLowerSha256 $path)-ne[string]$binding.sha256){throw "Pre-pilot provenance binding failed: $($binding.relativePath)"}}
New-Item -ItemType Directory -Path $root -Force|Out-Null;New-Item -ItemType Directory -Path (Join-Path $root 'Orchestration') -Force|Out-Null
$winps='C:\WINDOWS\System32\WindowsPowerShell\v1.0\powershell.exe';$native=@('C:\Users\bdscy\Documents\WindowsPowerShell\Modules','C:\Program Files\WindowsPowerShell\Modules','C:\WINDOWS\System32\WindowsPowerShell\v1.0\Modules')-join';'
function Invoke-Step([string]$Name,[string]$Script,[string[]]$Arguments){$stdout=Join-Path $root ('Orchestration\'+$Name+'.stdout.log');$stderr=Join-Path $root ('Orchestration\'+$Name+'.stderr.log');$old=$env:PSModulePath;try{$env:PSModulePath=$native;&$winps -NoProfile -ExecutionPolicy Bypass -File $Script @Arguments 1>$stdout 2>$stderr;$exit=[int]$LASTEXITCODE}finally{$env:PSModulePath=$old};if($exit-ne0){throw "$Name failed: exit=$exit stderr=$stderr"}}
function Write-Checkpoint([string]$Status,[string]$Message){$value=[ordered]@{schemaVersion=1;checkpointKind='gate13r-pr1b-prepilot-checkpoint-v1';savedAtUtc=[DateTime]::UtcNow.ToString('o');status=$Status;message=$Message;pilotPlanSha256=Get-Gate13RPR1BLowerSha256 $PilotPlanPath;provenanceSha256=Get-Gate13RPR1BLowerSha256 $ProvenancePath;formalCampaign=$false;gate13rFormalAuthorized=$false};Write-Gate13RPR1BAtomicUtf8NoBomJson -Path (Join-Path $root 'checkpoint.json') -Value $value -Depth 15}
function Write-Partial([string]$Status){$files=@(Get-ChildItem -LiteralPath $root -Recurse -File -Force|Where-Object{$_.Name-notlike'*.tmp-*' -and$_.Name-ne'partial-output-manifest.json'});$rows=@($files|ForEach-Object{[pscustomobject][ordered]@{relativePath=Get-Gate13RPR1BProjectRelativePath $ProjectPath $_.FullName;rawBytes=[long]$_.Length;sha256=Get-Gate13RPR1BLowerSha256 $_.FullName}});Write-Gate13RPR1BAtomicUtf8NoBomJson -Path (Join-Path $root 'partial-output-manifest.json') -Value ([ordered]@{schemaVersion=1;status=$Status;savedAtUtc=[DateTime]::UtcNow.ToString('o');fileCount=$rows.Count;files=$rows;formalCampaign=$false}) -Depth 30}
try{
    $receipt=[ordered]@{schemaVersion=1;receiptKind='gate13r-pr1b-prepilot-execution-receipt-v1';createdAtUtc=[DateTime]::UtcNow.ToString('o');verificationRoot=$root;pilotPlanSha256=Get-Gate13RPR1BLowerSha256 $PilotPlanPath;provenanceSha256=Get-Gate13RPR1BLowerSha256 $ProvenancePath;unitySha256=Get-Gate13RPR1BLowerSha256 $UnityPath;nonFormal=$true;formalCampaign=$false;gate13rFormalAuthorized=$false};Write-Gate13RPR1BAtomicUtf8NoBomJson -Path (Join-Path $root 'execution-receipt.json') -Value $receipt -Depth 15;Write-Checkpoint 'started' $null
    Invoke-Step '01-static-unit' (Join-Path $ProjectPath 'Research\Verification\Run-Gate13RPR1BStaticUnitV1.ps1') @('-ProjectPath',$ProjectPath,'-VerificationRoot',$root,'-PilotPlanPath',$PilotPlanPath,'-ProvenancePath',$ProvenancePath);Write-Checkpoint 'static-unit-passed' $null
    Invoke-Step '02-compile' (Join-Path $ProjectPath 'Research\Verification\Run-Gate12RCompileV4.ps1') @('-ProjectPath',$ProjectPath,'-VerificationRoot',$root,'-UnityPath',$UnityPath);Write-Checkpoint 'compile-passed' $null
    $telemetryOutput=Join-Path $root 'TelemetryProbe\v1';Invoke-Step '03-telemetry' (Join-Path $ProjectPath 'Research\Run-Gate12RTelemetryProbeV3.ps1') @('-ProjectPath',$ProjectPath,'-OutputDirectory',$telemetryOutput,'-AllowedRoot',$root,'-UnityPath',$UnityPath);$telemetryResult=Join-Path $telemetryOutput 'telemetry-probe-result.json';Write-Checkpoint 'telemetry-passed' $null
    Invoke-Step '04-block-verification' (Join-Path $ProjectPath 'Research\Verification\Run-Gate13RPR1BBlockVerificationV1.ps1') @('-ProjectPath',$ProjectPath,'-VerificationRoot',$root,'-PilotPlanPath',$PilotPlanPath,'-ProvenancePath',$ProvenancePath,'-TelemetryResultPath',$telemetryResult,'-UnityPath',$UnityPath);Write-Checkpoint 'block-verification-passed' $null
    Invoke-Step '05-validation-only-audit' (Join-Path $ProjectPath 'Research\Verification\Run-Gate13RPR1BValidationOnlyPrePilotAuditV1.ps1') @('-ProjectPath',$ProjectPath,'-VerificationRoot',$root,'-PilotPlanPath',$PilotPlanPath,'-ProvenancePath',$ProvenancePath,'-TelemetryResultPath',$telemetryResult);$audit=Read-Gate13RPR1BJson (Join-Path $root 'ValidationOnlyPrePilotAudit.summary.json');if($audit.passed-ne$true-or$audit.pilotExecutionAuthorized-ne$true){throw 'Final validation-only audit did not authorize pilot execution.'}
    Write-Checkpoint 'PREPILOT-PASSED-PILOT-AUTHORIZED' $null;Write-Partial 'PREPILOT-PASSED-PILOT-AUTHORIZED';Write-Host 'PR1B pre-pilot gates passed.' -ForegroundColor Green;exit 0
}catch{$message=$_.Exception.ToString();$failure=[ordered]@{schemaVersion=1;receiptKind='gate13r-pr1b-prepilot-failure-receipt-v1';failedAtUtc=[DateTime]::UtcNow.ToString('o');message=$message;status='FAILED-NO-PILOT';formalCampaign=$false;gate13rFormalAuthorized=$false};Write-Gate13RPR1BAtomicUtf8NoBomJson -Path (Join-Path $root 'failure-receipt.json') -Value $failure -Depth 15;Write-Checkpoint 'failed-no-pilot' $message;Write-Partial 'failed-no-pilot';Write-Error "PR1B pre-pilot failed closed: $message";exit 1}
